import sys
from functools import lru_cache

data = sys.stdin.read().split()
n = int(data[0])
a = tuple(map(int, data[1:1 + n]))

@lru_cache(maxsize=None)
def best(state):
    if not state:
        return 0
    res = 0
    m = len(state)
    for i in range(m):
        if m == 1:
            gain = state[0]
        elif i == 0:
            gain = state[1]
        elif i == m - 1:
            gain = state[m - 2]
        else:
            gain = state[i - 1] * state[i + 1]
        res = max(res, gain + best(state[:i] + state[i + 1:]))
    return res

print(best(a))

